import {loginScreen, logoutButton, administration} from './access.js';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 11h18M8 15h2m4 0h2m-8 3h2"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',plus:'<path d="M12 5v14M5 12h14"/>',chevron:'<path d="m9 5 7 7-7 7"/>',left:'<path d="m15 5-7 7 7 7"/>',down:'<path d="m6 9 6 6 6-6"/>',room:'<path d="M4 21h16M6 21V4l10-2v19M16 6h3v15M12 12h.01"/>',meetings:'<rect x="4" y="3" width="16" height="18" rx="2"/><path d="M8 8h8M8 12h8M8 16h5"/>',shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6Z"/><path d="m8 12 3 3 5-6"/>',help:'<circle cx="12" cy="12" r="9"/><path d="M9.5 9a2.5 2.5 0 1 1 3 2.5c-.5.3-.5.5-.5 2M12 17h.01"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',users:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3m0-16a3 3 0 0 1 0 6m3 4a5 5 0 0 1 3 6"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V6a4 4 0 0 1 8 0v4M12 14v3"/>',link:'<path d="m10 13 4-4M8 16l-1 1a4 4 0 0 1-6-6l4-4a4 4 0 0 1 6 0m2 1 1-1a4 4 0 0 1 6 6l-4 4a4 4 0 0 1-6 0" transform="translate(1 1)"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',refresh:'<path d="M20 7v5h-5M4 17v-5h5M5 7a8 8 0 0 1 13-2l2 2M4 17l2 2a8 8 0 0 0 13-2"/>',check:'<path d="m5 12 4 4L19 6"/>',repeat:'<path d="m16 3 4 4-4 4M4 10V7h16M8 21l-4-4 4-4m12 1v3H4"/>'};
const ic=(name,cls='')=>`<svg class="${cls}" viewBox="0 0 24 24" aria-hidden="true">${icons[name]||icons.calendar}</svg>`;
const demo=window.PORTAL_CONFIG?.demo===true;
let demoModule,me,bookings=[],page='schedule',view='day',selectedDate=today(),filter='upcoming',search='',busy=false,refreshing=false,modalReturn=null;
let form=null,detail=null,versions={};
function today(){return new Date().toLocaleDateString('sv-SE',{timeZone:'Asia/Yekaterinburg'})}
const localDate=d=>new Date(d).toLocaleDateString('sv-SE',{timeZone:'Asia/Yekaterinburg'});
const time=d=>new Date(d).toLocaleTimeString('ru-RU',{timeZone:'Asia/Yekaterinburg',hour:'2-digit',minute:'2-digit'});
const at=(d,t)=>`${d}T${t}:00+05:00`;
const dayAdd=(d,n)=>localDate(new Date(new Date(at(d,'12:00')).getTime()+n*86400000));
const dateFormat=(d,options={day:'numeric',month:'long'})=>new Date(at(d,'12:00')).toLocaleDateString('ru-RU',{timeZone:'Asia/Yekaterinburg',...options});
const initials=name=>name.split(' ').slice(0,2).map(s=>s[0]).join('');
const min=t=>+t.slice(0,2)*60+ +t.slice(3,5);
const hm=m=>String(Math.floor(m/60)).padStart(2,'0')+':'+String(m%60).padStart(2,'0');
const uuid=()=>crypto.randomUUID();
const roomName=n=>`Переговорная ${n} этаж`;
function toast(text){$('#toast').className='toast';$('#toast').textContent=text;clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>{$('#toast').className='';$('#toast').textContent=''},4200)}
async function api(path,method='GET',body){
 if(demo){demoModule??=await import('./demo.js');return demoModule.demoApi(path,method,body)}
 const r=await fetch(path,{method,credentials:'same-origin',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});
 let data;try{data=await r.json()}catch{throw new Error(r.status===401?'Выполните корпоративный вход.':'Сервер не ответил. Повторите запрос.')}
 if(!r.ok){let d=data.detail||'Ошибка запроса';let e=new Error(typeof d==='string'?d:d.message||'Проверьте заполнение полей.');e.conflicts=d.conflicts;e.status=r.status;throw e}return data;
}
function weekStart(d){return dayAdd(d,-((new Date(at(d,'12:00')).getDay()+6)%7))}
async function load(){
 const start=page==='mine'?dayAdd(today(),-365):view==='week'?weekStart(selectedDate):selectedDate;
 const end=page==='mine'?dayAdd(today(),61):dayAdd(start,view==='week'?7:1);
 bookings=await api(`/api/bookings?start=${encodeURIComponent(at(start,'00:00'))}&end=${encodeURIComponent(at(end,'00:00'))}${page==='mine'?'&mine=true':''}`);
}
function shell(){
 $('#app').innerHTML=`<div class="shell"><aside class="sidebar"><img class="brand" src="/assets/logo.png" alt="УГМК-Застройщик"><div class="side-caption">Рабочее пространство</div><nav class="nav" aria-label="Главное меню">${[['schedule','calendar','Расписание'],['mine','meetings','Мои встречи'],...(me.admin?[['admin','shield','Управление']]:[]),['rules','help','Правила бронирования']].map(([id,icon,name])=>`<button data-page="${id}" class="${page===id?'active':''}">${ic(icon)}${name}${id==='mine'?'<span class="badge">Мои</span>':''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="side-tip"><strong>${ic('clock')} Время для важных встреч</strong>Переговорные доступны<br>каждый день с 07:00 до 21:00.<br>Планируйте на 60 дней вперёд.</div><div class="user"><div class="avatar">${esc(initials(me.name))}</div><div class="user-text"><b>${esc(me.name)}</b><small>${esc(me.department||'Сотрудник')}</small>${demo?`<select id="demo-user" aria-label="Демонстрационная роль">${demoModule.people.map(p=>`<option value="${p.id}" ${p.id===me.id?'selected':''}>${p.admin?'Администратор':p.delegate?'Секретариат':'Сотрудник'} · ${p.name.split(' ')[0]}</option>`).join('')}</select>`:''}</div></div></div></aside><main class="main"><header class="topbar"><div>Корпоративный портал <span class="crumb">/ &nbsp;Переговорные</span></div><div class="topbar-right">${demo?'<span class="demo-pill">ДЕМО · ВЫМЫШЛЕННЫЕ ДАННЫЕ</span>':''}<span class="timezone">${ic('clock')} Екатеринбург <span class="muted">UTC+5</span></span></div></header><div class="content" id="content"></div></main></div>`;
 $$('[data-page]').forEach(b=>b.onclick=()=>navigate(b.dataset.page));
 if(!demo)logoutButton(api);
 if($('#demo-user'))$('#demo-user').onchange=async e=>{demoModule.switchUser(e.target.value);me=await api('/api/me');page='schedule';await refresh();toast('Демонстрационная роль изменена')};
}
async function navigate(p){page=p;shell();await refreshContent()}
function title(name,sub,action=true){return `<div class="page-title"><div><div class="eyebrow">УГМК-ЗАСТРОЙЩИК / ПЕРЕГОВОРНЫЕ</div><h1>${name}</h1><p>${sub}</p></div>${action?`<button class="btn primary" id="new-booking">${ic('plus')} Забронировать</button>`:''}</div>`}
function footer(){return `<footer class="page-footer"><span>УГМК-Застройщик · Корпоративное пространство</span><span>${demo?'Демонстрация · AD не подключён':'Внутренний сервис'} &nbsp; © 2026</span></footer>`}
function roomCards(){return `<div class="room-cards">${[1,2].map(n=>{const rows=bookings.filter(b=>b.room===n&&b.status==='active'&&localDate(b.starts)===selectedDate),current=selectedDate===today()?rows.find(b=>new Date(b.starts)<=new Date()&&new Date(b.ends)>new Date()):null;const duration=rows.reduce((a,b)=>a+(new Date(b.ends)-new Date(b.starts))/3600000,0);return `<section class="room-card"><div class="room-icon">${ic('room')}</div><div class="room-main"><h2>${roomName(n)}</h2><div class="room-meta"><span class="room-status ${current?'busy':''}">${current?'Занята до '+time(current.ends):selectedDate===today()?'Свободна сейчас':'Доступна для бронирования'}</span><span>${rows.length} ${rows.length===1?'бронь':'брони'} на день</span></div></div><div class="room-right"><strong>${Math.max(0,14-duration).toLocaleString('ru-RU',{maximumFractionDigits:1})} ч</strong>свободно за день</div></section>`}).join('')}</div>`}
function schedule(){
 const start=weekStart(selectedDate),label=view==='day'?dateFormat(selectedDate):`${dateFormat(start,{day:'numeric'})}–${dateFormat(dayAdd(start,6))}`;
 $('#content').innerHTML=title('Расписание переговорных','Выберите свободное время — остальное займёт пару кликов.')+roomCards()+`<section class="calendar-card"><div class="calendar-toolbar"><div class="date-nav"><button class="btn" id="today">Сегодня</button><button class="icon-btn" id="prev" aria-label="Предыдущий период">${ic('left')}</button><button class="icon-btn" id="next" aria-label="Следующий период">${ic('chevron')}</button><label class="date-label">${label}<input type="date" value="${selectedDate}" id="pick-date" aria-label="Выбрать дату">${ic('down')}</label></div><div class="view-switch"><button data-view="day" class="${view==='day'?'active':''}">День</button><button data-view="week" class="${view==='week'?'active':''}">Неделя</button></div></div><div class="calendar-sub"><div class="legend"><span><i class="olive"></i> Мои встречи</span><span><i></i> Занято</span><span><i class="gray"></i> Недоступно</span></div><span>Нажмите на свободное время, чтобы забронировать</span></div><div class="calendar-scroll" id="calendar-scroll">${view==='day'?dayGrid():weekGrid()}</div><div class="calendar-footer"><span>${ic('lock')} Цель и участники видны только тем, у кого есть доступ к встрече</span><span>Шаг 15 минут · Встреча до 4 часов</span></div></section>`+footer();
 $('#new-booking').onclick=()=>openForm();$('#today').onclick=()=>changeDate(today());$('#prev').onclick=()=>changeDate(dayAdd(selectedDate,view==='day'?-1:-7));$('#next').onclick=()=>changeDate(dayAdd(selectedDate,view==='day'?1:7));$('#pick-date').onchange=e=>e.target.value&&changeDate(e.target.value);
 $$('[data-view]').forEach(b=>b.onclick=async()=>{view=b.dataset.view;await refreshContent()});
 $$('[data-booking]').forEach(b=>b.onclick=()=>openDetail(b.dataset.booking));
 $$('[data-slot]').forEach(b=>b.onclick=()=>openForm({room:+b.dataset.room,date:b.dataset.date,start:b.dataset.slot}));
 if(view==='day')$('#calendar-scroll').scrollTop=110;
}
function dayGrid(){
 let html=`<div class="day-head"><div>UTC+5</div><div>${roomName(1)} <small>1 этаж</small></div><div>${roomName(2)} <small>2 этаж</small></div></div><div class="day-body"><div class="time-axis">${Array.from({length:14},(_,i)=>`<span class="time-label" style="top:${i*72}px">${hm(420+i*60)}</span>`).join('')}</div>`;
 for(const room of [1,2]){
 html+=`<div class="room-column">${Array.from({length:56},(_,i)=>{const t=hm(420+i*15);return `<button class="slot" data-slot="${t}" data-room="${room}" data-date="${selectedDate}" aria-label="Забронировать: ${roomName(room)}, ${t}" ${new Date(at(selectedDate,t))<new Date()||selectedDate>dayAdd(today(),60)||bookings.some(b=>b.status==='active'&&b.room===room&&new Date(b.starts)<new Date(at(selectedDate,hm(420+(i+1)*15)))&&new Date(b.ends)>new Date(at(selectedDate,t)))?'disabled':''}></button>`}).join('')}`;
 html+=bookings.filter(b=>b.room===room&&b.status==='active'&&localDate(b.starts)===selectedDate).map(b=>{const s=min(time(b.starts)),e=min(time(b.ends)),height=(e-s)*1.2;return `<button data-booking="${b.id}" class="booking ${b.organizer.id===me.id?'own':''} ${b.kind==='block'?'blocked':''} ${height<30?'tiny':height<65?'short':''}" style="top:${(s-420)*1.2}px;height:${Math.max(16,height-3)}px" aria-label="${esc(b.title)}, ${time(b.starts)}–${time(b.ends)}, ${esc(b.organizer.name)}"><span class="booking-time">${time(b.starts)} – ${time(b.ends)} ${b.series_id?ic('repeat'):''}${!b.can_view?ic('lock'):''}</span><span class="booking-title">${esc(b.title)}</span><span class="booking-person">${esc(b.organizer.name)}${b.organizer.id===me.id?' · Организатор':''}</span></button>`}).join('')+'</div>';
 }
 const current=min(time(new Date()));if(selectedDate===today()&&current>=420&&current<1260)html+=`<div class="now-line" style="top:${(current-420)*1.2}px"></div>`;
 return html+'</div>';
}
function weekGrid(){return `<div class="week-grid">${Array.from({length:7},(_,i)=>{const d=dayAdd(weekStart(selectedDate),i);return `<div class="week-day ${d===today()?'today':''}"><h3>${dateFormat(d,{weekday:'short'})}<strong>${dateFormat(d,{day:'numeric'})}</strong></h3>${bookings.filter(b=>b.status==='active'&&localDate(b.starts)===d).map(b=>`<button class="week-event ${b.organizer.id===me.id?'own':''}" data-booking="${b.id}">${time(b.starts)}–${time(b.ends)} · ${b.room} этаж<b>${esc(b.title)}</b>${esc(b.organizer.name)}</button>`).join('')}<button class="week-add" data-slot="09:00" data-room="1" data-date="${d}" ${d<today()||d>dayAdd(today(),60)?'disabled':''}>+ Встреча</button></div>`}).join('')}</div>`}
async function changeDate(d){selectedDate=d;await refreshContent()}
function myMeetings(){
 const rows=bookings.filter(b=>(filter==='upcoming'?b.status==='active'&&new Date(b.ends)>=new Date():filter==='past'?b.status==='active'&&new Date(b.ends)<new Date():b.status==='cancelled')&&(b.title+' '+b.organizer.name).toLowerCase().includes(search.toLowerCase())).sort((a,b)=>(filter==='past'?-1:1)*(new Date(a.starts)-new Date(b.starts)));
 $('#content').innerHTML=title('Мои встречи','Ваши бронирования, приглашённые встречи и созданные поручения.')+`<section class="list-panel"><div class="list-toolbar"><div class="view-switch">${[['upcoming','Предстоящие'],['past','Прошедшие'],['cancelled','Отменённые']].map(([v,t])=>`<button data-filter="${v}" class="${filter===v?'active':''}">${t}</button>`).join('')}</div><input id="search-meetings" class="control" placeholder="Найти встречу" aria-label="Найти встречу" value="${esc(search)}"></div>${rows.length?rows.map(b=>`<div class="meeting-row ${b.status==='cancelled'?'cancelled-row':''}" role="button" tabindex="0" data-booking="${b.id}"><div class="meeting-date"><b>${dateFormat(localDate(b.starts),{day:'numeric'})}</b>${dateFormat(localDate(b.starts),{month:'short'})}</div><div><h3>${esc(b.title)} ${b.series_id?'↻':''}</h3><p>${time(b.starts)}–${time(b.ends)} · ${esc(b.organizer.name)}</p></div><div class="row-room">${roomName(b.room)}</div><span class="tag ${b.status==='cancelled'?'cancelled':''}">${b.status==='cancelled'?'Отменена':b.organizer.id===me.id?'Организатор':'Участие'}</span>${ic('chevron')}</div>`).join(''):`<div class="empty">${ic('calendar')}<h3>Здесь пока нет встреч</h3>Забронируйте переговорную — встреча появится в этом списке.</div>`}</section>`+footer();
 $('#new-booking').onclick=()=>openForm();$$('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;myMeetings()});$('#search-meetings').oninput=e=>{const pos=e.target.selectionStart;search=e.target.value;myMeetings();$('#search-meetings').focus();$('#search-meetings').setSelectionRange(pos,pos)};$$('[data-booking]').forEach(b=>{b.onclick=()=>openDetail(b.dataset.booking);b.onkeydown=e=>{if(e.key==='Enter')b.click()}});
}
function rules(){ $('#content').innerHTML=title('Правила бронирования','Всё, что нужно знать перед встречей.',false)+`<div class="rules-grid"><section class="rule-card"><h3>Планируйте свободно</h3>Обе переговорные доступны <b>ежедневно, 07:00–21:00</b> по Екатеринбургу. Шаг — 15 минут, длительность — от 15 минут до 4 часов. Горизонт — 60 дней. Согласование не требуется.</section><section class="rule-card"><h3>Встреча остаётся конфиденциальной</h3>Все видят время, комнату и организатора. Название, цель и участники доступны организатору, участникам, администратору и автору с действующим правом делегирования.</section><section class="rule-card"><h3>Повторяющиеся встречи</h3>Ежедневно или по дням недели, с датой окончания. При конфликте измените время или явно исключите занятые даты. Можно изменить один экземпляр либо будущую часть серии.</section><section class="rule-card"><h3>Календарь Outlook</h3>Скачайте .ics отдельной встречи и откройте его в Outlook. Приглашения отправляются вручную. <b>Изменения и отмены не синхронизируются</b>: обновляйте событие в Outlook самостоятельно.</section><section class="rule-card"><h3>Управление бронированием</h3>Будущую встречу можно перенести или отменить. Начавшуюся — завершить досрочно или продлить, если время свободно. Пересечения запрещены для всех пользователей.</section><section class="rule-card"><h3>Бронирование по поручению</h3>Выбрать другого организатора может только группа <b>secretary</b>. Организатор и автор сохраняются отдельно. Администраторов назначают в разделе управления порталом.</section></div>${demo?'<div class="hint">Это демонстрационный режим. Сотрудники и встречи вымышлены, изменения сохраняются только в этом браузере. Реальный AD не подключён.</div>':''}`+footer()}
async function admin(){
 if(!me.admin){page='schedule';return refresh()}
 const logs=await api('/api/audit');
 $('#content').innerHTML=title('Управление','Недоступность переговорных и история действий.',false)+`<div class="hint">Администратор видит подробности встреч и может изменять чужие бронирования с указанием причины. Пересечения запрещены.</div><div style="margin:20px 0"><button class="btn primary" id="block-room">${ic('lock')} Заблокировать время</button></div><section class="list-panel"><div class="list-toolbar"><b>Журнал действий</b><span class="muted">Последние ${logs.length} записей</span></div>${logs.length?`<table class="audit-table"><thead><tr><th>ДАТА И ВРЕМЯ</th><th>СОТРУДНИК</th><th>ДЕЙСТВИЕ</th><th>ПРИЧИНА</th></tr></thead><tbody>${logs.map(a=>`<tr><td>${dateFormat(localDate(a.at))}<br><small>${time(a.at)}</small></td><td>${esc(a.actor.name)}</td><td>${esc(a.action)}</td><td>${esc(a.reason||'—')}</td></tr>`).join('')}</tbody></table>`:'<div class="empty">Действия появятся здесь после первого изменения.</div>'}</section>`+footer();$('#block-room').onclick=()=>openForm({kind:'block'});if(!demo)await administration(api,me);
}
async function refreshContent(){
 try{if(page==='rules')return rules();if(page==='admin')return await admin();await load();page==='mine'?myMeetings():schedule()}
 catch(e){$('#content').innerHTML=title('Не удалось загрузить данные','Проверьте подключение к корпоративной сети.',false)+`<div class="error-box">${esc(e.message)}</div><button class="btn" id="retry" style="margin-top:20px">Повторить</button>`;$('#retry').onclick=refreshContent}
}
async function refresh(){shell();await refreshContent()}
function showModal(name,sub,body,buttons=''){
 if(!$('#modal-root').children.length)modalReturn=document.activeElement;
 $('#modal-root').innerHTML=`<div class="modal-overlay"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><header class="modal-header"><div><div class="tiny-label">${detail?'Карточка встречи':'Бронирование переговорной'}</div><h2 id="modal-title">${name}</h2><p>${sub}</p></div><button class="icon-btn" id="close-modal" aria-label="Закрыть">${ic('close')}</button></header><div class="modal-body">${body}</div>${buttons?`<footer class="modal-footer">${buttons}</footer>`:''}</section></div>`;
 document.body.style.overflow='hidden';$('#close-modal').onclick=closeModal;$('#close-modal').focus();
}
function closeModal(){if(busy)return;$('#modal-root').innerHTML='';document.body.style.overflow='';form=null;detail=null;const u=new URL(location.href);u.searchParams.delete('meeting');history.replaceState({},'',u);modalReturn?.focus()}
document.addEventListener('keydown',e=>{if(!$('#modal-root').children.length)return;if(e.key==='Escape')closeModal();if(e.key==='Tab'){const nodes=$$('.modal button,.modal input,.modal select,.modal textarea,.modal a').filter(x=>!x.disabled&&x.offsetParent!==null);if(e.shiftKey&&document.activeElement===nodes[0]){e.preventDefault();nodes.at(-1).focus()}else if(!e.shiftKey&&document.activeElement===nodes.at(-1)){e.preventDefault();nodes[0].focus()}}});
function freshStart(d){if(d>today())return'09:00';const m=Math.ceil((min(time(new Date()))+1)/15)*15;return hm(Math.max(420,Math.min(1245,m)))}
function openForm(seed={},existing=null){
 detail=existing;const d=seed.date||selectedDate;
 let date=d<today()?today():d,start=seed.start||freshStart(date);
 if(date===today()&&min(time(new Date()))>=1245){date=dayAdd(date,1);start='09:00'}
 form={request_id:uuid(),room:1,date,start,end:hm(Math.min(1260,min(start)+60)),title:'',purpose:'',organizer:me.id,organizerPerson:me,participants:[],repeat:'none',until:dayAdd(date,7),weekdays:[(new Date(at(date,'12:00')).getDay()+6)%7],exclude:[],kind:'meeting',reason:'',scope:'one',versions:{},...seed};
 if(existing)Object.assign(form,{id:existing.id,room:existing.room,date:localDate(existing.starts),start:time(existing.starts),end:time(existing.ends),title:existing.title,purpose:existing.purpose,organizer:existing.organizer.id,organizerPerson:existing.organizer,participants:existing.participants,kind:existing.kind,version:existing.version,series_id:existing.series_id});
 renderForm();
}
function renderForm(){
 const f=form;const adminReason=f.kind==='block'||(me.admin&&detail&&detail.organizer.id!==me.id);
 showModal(f.id?'Изменить встречу':f.kind==='block'?'Недоступность комнаты':'Новая встреча','Время по Екатеринбургу · UTC+5',`<form id="booking-form"><div class="form-label">Переговорная <span class="required">*</span></div><div class="radio-rooms">${[1,2].map(n=>`<button type="button" data-room-pick="${n}" class="${f.room===n?'selected':''}">${ic('room')} ${roomName(n)}</button>`).join('')}</div>${f.series_id?`<label class="field"><span>Применить изменение</span><select name="scope"><option value="one" ${f.scope==='one'?'selected':''}>Только эта встреча</option><option value="future" ${f.scope==='future'?'selected':''}>Эта и следующие будущие встречи</option></select></label>`:''}<div class="fields three"><label class="field"><span>Дата <span class="required">*</span></span><input type="date" name="date" value="${f.date}" min="${today()}" max="${dayAdd(today(),60)}" required ${f.scope==='future'?'readonly':''}></label><label class="field"><span>Начало <span class="required">*</span></span><input type="time" name="start" value="${f.start}" min="07:00" max="20:45" step="900" required></label><label class="field"><span>Окончание <span class="required">*</span></span><input type="time" name="end" value="${f.end}" min="07:15" max="21:00" step="900" required></label></div><label class="field"><span>${f.kind==='block'?'Название блокировки':'Название встречи'} <span class="required">*</span></span><input name="title" value="${esc(f.title)}" placeholder="Например, обсуждение проекта" maxlength="160" required></label><label class="field"><span>Цель или повестка <span class="muted">· необязательно</span></span><textarea name="purpose" placeholder="О чём будете говорить на встрече" maxlength="4000">${esc(f.purpose)}</textarea></label><div class="form-section"><div class="form-label">Организатор</div><div class="readonly-person"><span class="avatar">${esc(initials(f.organizerPerson.name))}</span>${esc(f.organizerPerson.name)}${f.organizer===me.id?' · вы':''}</div>${me.delegate?'<label class="field" style="margin-top:12px"><input id="organizer-search" placeholder="Найти другого организатора" aria-label="Найти организатора"><span id="organizer-results"></span></label>':''}<label class="field" style="margin-top:20px"><span>Участники <span class="muted">· необязательно</span></span><input id="people-search" autocomplete="off" placeholder="Начните вводить имя или почту"><div id="people-results"></div><div class="chips">${f.participants.map(p=>`<span class="chip">${esc(p.name)}<button type="button" data-remove="${p.id}" aria-label="Удалить ${esc(p.name)}">×</button></span>`).join('')}</div><small>${demo?'В демонстрации используется вымышленный справочник.':'Поиск сотрудников в корпоративном справочнике.'}</small></label></div>${!f.id?`<div class="form-section"><label class="field"><span>Повторение</span><select name="repeat"><option value="none" ${f.repeat==='none'?'selected':''}>Не повторять</option><option value="daily" ${f.repeat==='daily'?'selected':''}>Ежедневно</option><option value="weekly" ${f.repeat==='weekly'?'selected':''}>Еженедельно по дням</option></select></label>${f.repeat==='weekly'?`<div class="weekdays">${['Пн','Вт','Ср','Чт','Пт','Сб','Вс'].map((n,i)=>`<button type="button" class="${f.weekdays.includes(i)?'on':''}" data-weekday="${i}">${n}</button>`).join('')}</div>`:''}${f.repeat!=='none'?`<label class="field"><span>Повторять до</span><input name="until" type="date" min="${f.date}" max="${dayAdd(today(),60)}" value="${f.until}" required></label><button type="button" class="btn" id="preview-series">${ic('check')} Проверить даты</button><div id="series-preview"></div>`:''}</div>`:''}${adminReason?`<label class="field" style="margin-top:20px"><span>Причина действия <span class="required">*</span></span><textarea name="reason" required maxlength="1000" placeholder="Причина попадёт в журнал действий">${esc(f.reason)}</textarea></label>`:''}<div class="hint">${ic('lock')} Название, повестка и участники доступны только сотрудникам с правом просмотра этой встречи.</div><div id="form-errors"></div></form>`,`<button class="btn" id="form-cancel">Отмена</button><button class="btn primary" id="form-save">${ic('check')} ${f.id?'Сохранить изменения':f.repeat==='none'?'Забронировать':'Создать серию'}</button>`);
 $('#form-cancel').onclick=closeModal;$('#form-save').onclick=saveForm;$('#booking-form').onsubmit=e=>{e.preventDefault();saveForm()};
 $$('[data-room-pick]').forEach(b=>b.onclick=()=>{readForm();form.room=+b.dataset.roomPick;renderForm()});
 $$('[data-remove]').forEach(b=>b.onclick=()=>{readForm();form.participants=form.participants.filter(p=>p.id!==b.dataset.remove);renderForm()});
 $$('[data-weekday]').forEach(b=>b.onclick=()=>{readForm();const d=+b.dataset.weekday;form.weekdays=form.weekdays.includes(d)?form.weekdays.filter(x=>x!==d):[...form.weekdays,d];renderForm()});
 ['repeat','scope'].forEach(name=>{const el=$(`[name="${name}"]`);if(el)el.onchange=()=>{readForm();form.exclude=[];renderForm()}});
 if($('#preview-series'))$('#preview-series').onclick=previewSeries;
 bindPeople('people',p=>{if(!form.participants.some(x=>x.id===p.id))form.participants.push(p)});
 if(me.delegate)bindPeople('organizer',p=>{form.organizer=p.id;form.organizerPerson=p});
 $('#booking-form').addEventListener('input',e=>{if(e.target.name){form.request_id=uuid();form.exclude=[]}});
}
function readForm(){if(!form||!$('#booking-form'))return;for(const [k,v] of new FormData($('#booking-form')))form[k]=v}
function payload(){readForm();const f={...form,participants:form.participants.map(p=>p.id)};delete f.organizerPerson;delete f.id;delete f.series_id;return f}
function bindPeople(type,onChoose){const input=$(`#${type==='people'?'people':'organizer'}-search`),target=$(`#${type}-results`);let timer,seq=0;input.oninput=()=>{clearTimeout(timer);const query=input.value,token=++seq;if(query.length<2){target.innerHTML='';return}timer=setTimeout(async()=>{try{const result=await api('/api/people?q='+encodeURIComponent(query));if(token!==seq||!target.isConnected)return;target.innerHTML=`<div class="search-results">${result.length?result.map((p,i)=>`<button type="button" data-person="${i}">${esc(p.name)}<small>${esc(p.department)} · ${esc(p.email)}</small></button>`).join(''):'<div class="hint">Ничего не найдено</div>'}</div>`;target.querySelectorAll('[data-person]').forEach(b=>b.onclick=()=>{readForm();onChoose(result[+b.dataset.person]);form.request_id=uuid();renderForm()})}catch(e){target.innerHTML=`<div class="error-box">${esc(e.message)}</div>`}},250)}}
function formError(e){$('#form-errors').innerHTML=`<div class="error-box">${esc(e.message)}</div>${e.conflicts?.length?`<div class="conflicts"><b>Занятые даты</b>${e.conflicts.map(c=>`<div>${dateFormat(c.date)} · ${c.start}–${c.end}</div>`).join('')}${form.repeat!=='none'?'<p>Исключите даты через «Проверить даты» и повторите сохранение.</p>':''}</div>`:''}`;$('#form-errors').scrollIntoView({block:'nearest',behavior:'smooth'})}
async function previewSeries(){if(!$('#booking-form').reportValidity())return;const f=payload();try{const result=await api('/api/bookings/preview','POST',f);$('#series-preview').innerHTML=`<div class="preview-dates">${result.dates.map(d=>`<span>${dateFormat(d,{day:'numeric',month:'short'})}</span>`).join('')}</div>${result.conflicts.length?`<div class="conflicts"><b>Исключить конфликтующие даты:</b>${result.conflicts.map(c=>`<label><input type="checkbox" data-exclude="${c.date}">${dateFormat(c.date)} · ${c.start}–${c.end}</label>`).join('')}</div>`:`<div class="hint">${result.dates.length} встреч · все выбранные даты свободны. Доступность будет повторно проверена при сохранении.</div>`}`;$$('[data-exclude]').forEach(c=>c.onchange=()=>{form.exclude=c.checked?[...form.exclude,c.dataset.exclude]:form.exclude.filter(d=>d!==c.dataset.exclude);form.request_id=uuid()})}catch(e){formError(e)}}
async function saveForm(){
 if(busy||!$('#booking-form').reportValidity())return;const f=payload();
 busy=true;$('#form-save').disabled=true;$('#form-save').textContent='Сохраняем…';
 try{if(f.scope==='future')f.versions=form.versions=Object.keys(form.versions).length?form.versions:await api(`/api/bookings/${form.id}/series`);const r=await api(form.id?`/api/bookings/${form.id}`:'/api/bookings',form.id?'PUT':'POST',f);const d=form.date;busy=false;closeModal();selectedDate=d;await refreshContent();toast(r.ids.length>1?`Создано или обновлено встреч: ${r.ids.length}`:'Бронирование сохранено');await openDetail(r.ids[0])}
 catch(e){formError(e)}finally{busy=false;if($('#form-save')){$('#form-save').disabled=false;$('#form-save').textContent=form?.id?'Сохранить изменения':'Забронировать'}}
}
async function openDetail(id){
 let b;try{b=await api('/api/bookings/'+id)}catch(e){if(e.status===403){const x=bookings.find(b=>b.id===id);showModal('Время занято','Подробности встречи закрыты',x?`<div class="detail-line">${ic('room')}<div><small>Место</small><b>${roomName(x.room)}</b></div></div><div class="detail-line">${ic('clock')}<div><small>Дата и время</small><b>${dateFormat(localDate(x.starts))} · ${time(x.starts)}–${time(x.ends)}</b></div></div><div class="detail-line">${ic('users')}<div><small>Организатор</small><b>${esc(x.organizer.name)}</b></div></div><div class="hint">Название, цель и участники доступны сотрудникам с правом просмотра.</div>`:`<div class="hint">${esc(e.message)}</div>`);return}toast(e.message);return}
 detail=b;form=null;versions={};
 if(b.series_id&&b.can_edit)try{versions=await api(`/api/bookings/${b.id}/series`)}catch{}
 const future=new Date(b.starts)>new Date(),ongoing=new Date(b.starts)<=new Date()&&new Date(b.ends)>new Date(),active=b.status==='active';
 const u=new URL(location.href);u.searchParams.set('meeting',b.id);history.replaceState({},'',u);
 showModal('Встреча',b.series_id?'Повторяющаяся встреча · отдельный экземпляр':'Бронирование переговорной',`<div class="detail-title">${esc(b.title)}</div>${!active?'<div class="cancel-note">Встреча отменена. Это время снова свободно.</div>':''}<div class="detail-line">${ic('room')}<div><small>Место встречи</small><b>${roomName(b.room)}</b></div></div><div class="detail-line">${ic('calendar')}<div><small>Дата и время · Екатеринбург</small><b>${dateFormat(localDate(b.starts),{day:'numeric',month:'long',weekday:'long'})}<br>${time(b.starts)} – ${time(b.ends)}</b></div></div><div class="detail-line">${ic('users')}<div><small>Организатор</small><b>${esc(b.organizer.name)}</b>${b.creator.id!==b.organizer.id?`<small>Создала(л): ${esc(b.creator.name)}</small>`:''}</div></div>${b.purpose?`<div class="form-label">Цель или повестка</div><div class="detail-purpose">${esc(b.purpose)}</div>`:''}<div class="form-label" style="margin-top:23px">Участники · ${b.participants.length}</div>${b.participants.length?b.participants.map(p=>`<div class="detail-line" style="margin:12px 0"><span class="avatar">${esc(initials(p.name))}</span><div><b>${esc(p.name)}</b><small>${esc(p.department)}</small></div></div>`).join(''):'<p class="notice">Участники не указаны.</p>'}<div class="detail-actions"><button class="btn" id="copy-link">${ic('link')} Ссылка на встречу</button><button class="btn" id="download-ics">${ic('download')} В Outlook (.ics)</button></div><div class="hint">В Outlook вручную добавьте событие и пригласите участников. Изменения и отмены в портале не обновляют Outlook автоматически.</div>${active&&b.can_edit?(b.series_id?'<label class="field"><span>Область действия</span><select id="action-scope"><option value="one">Только эта встреча</option><option value="future">Эта и следующие будущие встречи</option></select></label>':'')+(me.admin&&b.organizer.id!==me.id?'<label class="field"><span>Причина изменения или отмены</span><textarea id="action-reason" maxlength="1000" placeholder="Обязательно для администратора"></textarea></label>':'')+(ongoing?`<label class="field"><span>Продлить до</span><input type="time" id="extend-time" step="900" value="${hm(Math.min(1260,min(time(b.ends))+15))}"></label>`:''):''}<div id="detail-error"></div>`,active&&b.can_edit?`${future?'<button class="btn danger" id="cancel-booking">Отменить встречу</button><button class="btn primary" id="edit-booking">Изменить</button>':ongoing?'<button class="btn" id="finish-booking">Завершить сейчас</button><button class="btn primary" id="extend-booking">Продлить</button>':''}`:'');
 $('#copy-link').onclick=async()=>{try{await navigator.clipboard.writeText(location.origin+'/?meeting='+b.id);toast('Ссылка скопирована')}catch{toast('Ссылка на встречу находится в адресной строке')}};
 $('#download-ics').onclick=()=>downloadICS(b);
 if($('#edit-booking'))$('#edit-booking').onclick=()=>{const scope=$('#action-scope')?.value||'one',reason=$('#action-reason')?.value||'',v=versions;openForm({},b);form.scope=scope;form.reason=reason;form.versions=v;renderForm()};
 if($('#cancel-booking'))$('#cancel-booking').onclick=()=>doAction(b,'cancel');
 if($('#finish-booking'))$('#finish-booking').onclick=()=>doAction(b,'finish');
 if($('#extend-booking'))$('#extend-booking').onclick=()=>doAction(b,'extend');
}
async function doAction(b,action){
 if(busy)return;const scope=$('#action-scope')?.value||'one',reason=$('#action-reason')?.value||'';
 if(me.admin&&b.organizer.id!==me.id&&!reason.trim()){$('#detail-error').innerHTML='<div class="error-box">Укажите причину действия.</div>';return}
 if(action==='cancel'&&!window.confirm(scope==='future'?'Отменить эту и следующие будущие встречи серии?':'Отменить эту встречу и освободить время?'))return;
 if(action==='finish'&&!window.confirm('Завершить встречу сейчас и освободить переговорную?'))return;
 busy=true;try{await api(`/api/bookings/${b.id}/${action}`,'POST',{request_id:uuid(),version:b.version,versions,scope:action==='cancel'?scope:'one',reason,end:action==='extend'?at(localDate(b.starts),$('#extend-time').value):null});busy=false;await refreshContent();await openDetail(b.id);toast(action==='cancel'?'Бронирование отменено':action==='finish'?'Встреча завершена':'Встреча продлена')}catch(e){$('#detail-error').innerHTML=`<div class="error-box">${esc(e.message)}</div>`}finally{busy=false}
}
async function downloadICS(b){
 if(!demo){const r=await fetch(`/api/bookings/${b.id}/ics`);if(!r.ok){toast('Не удалось скачать событие. Проверьте доступ.');return}return saveBlob(await r.blob(),`meeting-${b.id}.ics`)}
 const stamp=d=>new Date(d).toISOString().replace(/[-:]/g,'').split('.')[0]+'Z';const lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//UGMK//Meeting Portal Demo//RU','METHOD:PUBLISH','BEGIN:VEVENT',`UID:${b.id}@demo.invalid`,`SEQUENCE:${b.version}`,`DTSTAMP:${stamp(new Date())}`,`DTSTART:${stamp(b.starts)}`,`DTEND:${stamp(b.ends)}`,'SUMMARY:Встреча в переговорной',`LOCATION:${roomName(b.room)}`,`URL:${location.origin}/?meeting=${b.id}`,`STATUS:${b.status==='cancelled'?'CANCELLED':'CONFIRMED'}`,'END:VEVENT','END:VCALENDAR'];
 const folded=lines.flatMap(line=>{let rows=[],part='';for(const c of line){if(new TextEncoder().encode(part+c).length>73){rows.push(part);part=' '+c}else part+=c}rows.push(part);return rows});saveBlob(new Blob([folded.join('\r\n')+'\r\n'],{type:'text/calendar;charset=utf-8'}),`meeting-${b.id}.ics`);toast('Файл .ics подготовлен для ручного добавления в Outlook');
}
function saveBlob(blob,name){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
async function boot(){try{me=await api('/api/me');await refresh();const id=new URL(location.href).searchParams.get('meeting');if(id)await openDetail(id)}catch(e){if(!demo&&e.status===401){try{return await loginScreen(api,boot)}catch(error){e=error}}$('#app').innerHTML='<div class="initial"><h2>Портал недоступен</h2><p>'+esc(e.message)+'</p><button class="btn" id="reload">Повторить</button></div>';$('#reload').onclick=()=>location.reload()}}
boot();
setInterval(async()=>{if(refreshing||document.hidden||$('#modal-root').children.length||!['schedule','mine'].includes(page))return;refreshing=true;try{const pos=$('#calendar-scroll')?.scrollTop;await load();page==='mine'?myMeetings():schedule();if(pos!==undefined&&$('#calendar-scroll'))$('#calendar-scroll').scrollTop=pos}catch{toast('Не удалось обновить расписание. Проверьте соединение.')}finally{refreshing=false}},60000);
